package com.coffeeshop.repository;import com.coffeeshop.dto.EmployeeCommands;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.EmployeeModels;import javax.sql.DataSource;import java.sql.*;import java.util.*;public final class JdbcEmployeeRepository implements EmployeeRepository{private final DataSource ds;public JdbcEmployeeRepository(DataSource d){ds=Objects.requireNonNull(d);}public List<EmployeeModels.Employee>find(String search){String sql="SELECT e.employee_id,e.employee_number,e.first_name,e.last_name,e.phone,e.email,e.job_title,e.hire_date,e.termination_date,e.employment_status,e.is_active,e.row_version,u.user_id,u.username,COALESCE(u.is_active,0),STRING_AGG(r.role_code,', '),u.row_version FROM dbo.employees e LEFT JOIN dbo.users u ON u.employee_id=e.employee_id LEFT JOIN dbo.user_roles ur ON ur.user_id=u.user_id LEFT JOIN dbo.roles r ON r.role_id=ur.role_id WHERE (?='' OR e.employee_number LIKE ? OR e.first_name LIKE ? OR e.last_name LIKE ? OR COALESCE(u.username,'') LIKE ?) GROUP BY e.employee_id,e.employee_number,e.first_name,e.last_name,e.phone,e.email,e.job_title,e.hire_date,e.termination_date,e.employment_status,e.is_active,e.row_version,u.user_id,u.username,u.is_active,u.row_version ORDER BY e.last_name,e.first_name";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql)){String q=search==null?"":search.trim(),like="%"+q+"%";s.setString(1,q);for(int i=2;i<=5;i++)s.setString(i,like);try(ResultSet r=s.executeQuery()){List<EmployeeModels.Employee>x=new ArrayList<>();while(r.next()){Long uid=r.getObject(13,Long.class);x.add(new EmployeeModels.Employee(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getDate(8).toLocalDate(),r.getDate(9)==null?null:r.getDate(9).toLocalDate(),r.getString(10),r.getBoolean(11),r.getBytes(12),uid,r.getString(14),r.getBoolean(15),r.getString(16),r.getBytes(17)));}return List.copyOf(x);}}catch(SQLException e){throw fail("Unable to load employees.",e);}}public List<EmployeeModels.Role>roles(){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("SELECT role_id,role_code,role_name FROM dbo.roles WHERE is_active=1 ORDER BY role_name");ResultSet r=s.executeQuery()){List<EmployeeModels.Role>x=new ArrayList<>();while(r.next())x.add(new EmployeeModels.Role(r.getLong(1),r.getString(2),r.getString(3)));return List.copyOf(x);}catch(SQLException e){throw fail("Unable to load roles.",e);}}public long saveEmployee(EmployeeCommands.SaveEmployee q){String sql=q.id()==null?"INSERT dbo.employees(employee_number,first_name,last_name,phone,email,job_title,hire_date,termination_date,employment_status,is_active) VALUES(?,?,?,?,?,?,?,?,?,?)":"UPDATE dbo.employees SET employee_number=?,first_name=?,last_name=?,phone=?,email=?,job_title=?,hire_date=?,termination_date=?,employment_status=?,is_active=?,updated_at=SYSUTCDATETIME() WHERE employee_id=? AND row_version=?";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){s.setString(1,q.number());s.setString(2,q.firstName());s.setString(3,q.lastName());nullable(s,4,q.phone());nullable(s,5,q.email());nullable(s,6,q.jobTitle());s.setDate(7,java.sql.Date.valueOf(q.hireDate()));if(q.terminationDate()==null)s.setNull(8,Types.DATE);else s.setDate(8,java.sql.Date.valueOf(q.terminationDate()));s.setString(9,q.status());s.setBoolean(10,q.active());if(q.id()!=null){s.setLong(11,q.id());s.setBytes(12,q.version());one(s.executeUpdate());return q.id();}s.executeUpdate();return key(s);}catch(SQLException e){throw fail("Unable to save employee. Check number and email uniqueness.",e);}}public void setEmployeeActive(long id,boolean active,byte[]v){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("UPDATE dbo.employees SET is_active=?,updated_at=SYSUTCDATETIME() WHERE employee_id=? AND row_version=?")){s.setBoolean(1,active);s.setLong(2,id);s.setBytes(3,v);one(s.executeUpdate());}catch(SQLException e){throw fail("Unable to update employee.",e);}}public void saveUser(EmployeeCommands.SaveUser q,String hash,long actor){try(Connection c=ds.getConnection()){c.setAutoCommit(false);try{long uid;if(q.userId()==null){try(PreparedStatement s=c.prepareStatement("INSERT dbo.users(employee_id,username,password_hash,must_change_password,is_active) VALUES(?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,q.employeeId());s.setString(2,q.username());s.setString(3,hash);s.setBoolean(4,q.mustChange());s.setBoolean(5,q.active());s.executeUpdate();uid=key(s);}}else{uid=q.userId();String sql=hash==null?"UPDATE dbo.users SET username=?,must_change_password=?,is_active=?,updated_at=SYSUTCDATETIME() WHERE user_id=? AND row_version=?":"UPDATE dbo.users SET username=?,password_hash=?,password_changed_at=SYSUTCDATETIME(),failed_login_count=0,locked_until=NULL,must_change_password=?,is_active=?,updated_at=SYSUTCDATETIME() WHERE user_id=? AND row_version=?";try(PreparedStatement s=c.prepareStatement(sql)){int i=1;s.setString(i++,q.username());if(hash!=null)s.setString(i++,hash);s.setBoolean(i++,q.mustChange());s.setBoolean(i++,q.active());s.setLong(i++,uid);s.setBytes(i,q.version());one(s.executeUpdate());}}try(PreparedStatement d=c.prepareStatement("DELETE FROM dbo.user_roles WHERE user_id=?")){d.setLong(1,uid);d.executeUpdate();}try(PreparedStatement s=c.prepareStatement("INSERT dbo.user_roles(user_id,role_id,assigned_by_user_id) VALUES(?,?,?)")){for(long role:q.roleIds()){s.setLong(1,uid);s.setLong(2,role);s.setLong(3,actor);s.addBatch();}s.executeBatch();}c.commit();}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to save user account.",e);}}private static void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null)s.setNull(i,Types.NVARCHAR);else s.setString(i,v);}private static void one(int n){if(n!=1)throw new IllegalStateException("Record changed. Refresh and try again.");}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){r.next();return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
